    background: #3f0e40;
    color: #cfc3cf;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.sidebar-header {
    padding: 16px 16px 8px;
}

    .sidebar-header h3 {
        margin: 0;
        color: #fff;
        font-size: 1.1rem;
        font-weight: 700;
    }

.channel-list {
    list-style: none;
    margin: 0;
    padding: 4px 0;
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    padding: 6px 16px;
    cursor: pointer;
    border-radius: 6px;
    margin: 0 8px;
    transition: background 0.12s;
}

    .channel-item:hover {
        background: rgba(255,255,255,0.08);
    }

    .channel-item.active {
        background: #1264a3;
        color: #fff;
    }

.channel-name {
    font-weight: 600;
    font-size: 0.93rem;
    flex: 1;
}

.channel-desc {
    width: 100%;
    font-size: 0.78rem;
    opacity: 0.7;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    margin-top: 1px;
}

.unread-badge {
    background: #e01e5a;
    color: #fff;
    border-radius: 10px;
    padding: 1px 7px;
    font-size: 0.75rem;
    font-weight: 700;
    margin-left: auto;
}

/* ───────── Main Message Area ───────── */

.message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
    border-right: 1px solid #e8e8e8;
}

.message-header {
    padding: 12px 20px 8px;
    border-bottom: 1px solid #e8e8e8;
}

    .message-header h2 {
        margin: 0;
        font-size: 1.1rem;
        font-weight: 700;
    }

    .message-header p {
        margin: 2px 0 0;
        font-size: 0.82rem;
        color: #616061;
    }

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 20px;
}

.loading-indicator {
    text-align: center;
    padding: 10px;
    color: #999;
    font-size: 0.85rem;
}

.empty-state {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #999;
    font-size: 1.1rem;
}

/* ── Message Row ── */

.message-row {
    display: flex;
    align-items: flex-start;
    padding: 6px 0;
    position: relative;
    border-radius: 6px;
