    .message-row:hover {
        background: #f8f8f8;
    }

.message-bubble {
    flex: 1;
    min-width: 0;
}

.message-meta {
    display: flex;
    align-items: baseline;
    gap: 8px;
}

.author {
    font-weight: 700;
    font-size: 0.9rem;
}

.timestamp {
    font-size: 0.75rem;
    color: #999;
}

.message-content {
    margin-top: 2px;
    font-size: 0.93rem;
    line-height: 1.45;
